mapper.select:
SELECT COUNT(*)
FROM equipment_oee_target
WHERE tenant_id = #{tenantId}
  AND target_level = #{request.targetLevel}
  AND organization_id <=> #{request.organizationId}
  AND equipment_id <=> #{request.equipmentId}
  AND status = 1
  AND deleted = 0
  AND effective_start_date <= COALESCE(#{request.effectiveEndDate}, '9999-12-31')
  AND COALESCE(effective_end_date, '9999-12-31') >= #{request.effectiveStartDate}
  AND id != #{excludeId}

