mapper.select:
SELECT 
FROM equipment_output_record p
JOIN equipment e
  ON e.tenant_id = p.tenant_id AND e.id = p.equipment_id AND e.deleted = 0
JOIN organization o
  ON o.tenant_id = p.tenant_id AND o.id = p.organization_id AND o.deleted = 0
JOIN equipment_shift s
  ON s.tenant_id = p.tenant_id AND s.id = p.shift_id AND s.deleted = 0
WHERE p.tenant_id = #{tenantId}
  AND p.equipment_id = #{equipmentId}
  AND p.production_date = #{productionDate}
  AND p.shift_id = #{shiftId}
  AND p.deleted = 0

mapper.update:
UPDATE equipment_output_record
SET deleted = 1, updated_by = #{operatorId}, version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND version = #{version}
  AND deleted = 0

UPDATE equipment_oee_record
SET planned_quantity = #{request.plannedQuantity},
    actual_quantity = #{request.actualQuantity},
    good_quantity = #{request.goodQuantity},
    defective_quantity = #{request.defectiveQuantity},
    source_type = #{request.sourceType},
    data_status = 'DRAFT',
    approved_by = NULL,
    approved_time = NULL,
    updated_by = #{operatorId}
WHERE tenant_id = #{tenantId}
  AND equipment_id = #{request.equipmentId}
  AND production_date = #{request.productionDate}
  AND shift_id = #{request.shiftId}
  AND data_status != 'LOCKED'
  AND deleted = 0

UPDATE equipment_oee_record
SET planned_quantity = 0,
    actual_quantity = 0,
    good_quantity = 0,
    defective_quantity = 0,
    data_status = 'DRAFT',
    approved_by = NULL,
    approved_time = NULL,
    updated_by = #{operatorId}
WHERE tenant_id = #{tenantId}
  AND equipment_id = #{equipmentId}
  AND production_date = #{productionDate}
  AND shift_id = #{shiftId}
  AND data_status != 'LOCKED'
  AND deleted = 0

