mapper.select:
SELECT COALESCE(SUM(d.duration_minutes), 0)
FROM equipment_downtime_record d
JOIN equipment_loss_reason reason
  ON reason.tenant_id = d.tenant_id
 AND reason.id = d.loss_reason_id
 AND reason.deleted = 0
WHERE d.tenant_id = #{tenantId}
  AND d.equipment_id = #{equipmentId}
  AND d.production_date = #{productionDate}
  AND d.shift_id = #{shiftId}
  AND d.planned_flag = #{plannedFlag}
  AND d.deleted = 0
  AND (
      (#{plannedFlag} = 0 AND reason.affects_metric = 'AVAILABILITY')
      OR #{plannedFlag} = 1
  )

